package school.magiccodex.paper;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import school.magiccodex.protocol.GeneralPresetProtocol;
class GeneralPresetPolicyTest{
 @Test void hiddenAndUnknownSpellCooldownsBlockEverySwitchWithoutMutation(){var cds=new HashMap<String,Long>();cds.put("hidden_previous_preset",5000L);var before=Map.copyOf(cds);assertEquals(1,GeneralPresetPolicy.status(1,2,true,false,false,cds,100));assertEquals(before,cds);assertEquals(0,GeneralPresetPolicy.status(1,2,true,false,false,cds,5000));}
 @Test void combatAndCastingAndNotReadyFailClosed(){assertEquals(2,GeneralPresetPolicy.status(2,1,true,true,false,Map.of(),0));assertEquals(1,GeneralPresetPolicy.status(2,1,true,false,true,Map.of(),0));assertEquals(3,GeneralPresetPolicy.status(2,1,false,false,false,Map.of(),0));}
 @Test void queryAndSameSelectionDoNotChangeCooldowns(){assertEquals(0,GeneralPresetPolicy.status(2,0,true,true,true,Map.of("a",100L),0));assertEquals(0,GeneralPresetPolicy.status(2,2,true,true,true,Map.of("a",100L),0));}
 @Test void packetsRejectMalformedVersionsIndexesAndSequences(){for(int i=0;i<=2;i++){var req=new GeneralPresetProtocol.Request(1,i);assertEquals(req,GeneralPresetProtocol.request(GeneralPresetProtocol.encode(req)));}assertThrows(IllegalArgumentException.class,()->GeneralPresetProtocol.request(new byte[100]));assertThrows(IllegalArgumentException.class,()->GeneralPresetProtocol.encode(new GeneralPresetProtocol.Request(0,1)));assertThrows(IllegalArgumentException.class,()->GeneralPresetProtocol.encode(new GeneralPresetProtocol.Request(2,3)));var b=GeneralPresetProtocol.encode(new GeneralPresetProtocol.Request(1,2));b[0]=2;assertThrows(IllegalArgumentException.class,()->GeneralPresetProtocol.request(b));}
}
